import java.util.Scanner;

public class div25 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine();
        char[] chars = line.toCharArray();
        int length = chars.length;
        int totalWays = 0;
        if (length == 1) {
            if (chars[0] == 'X' || chars[0] == '_' || Character.getNumericValue(chars[0]) == 0) {
                totalWays = 1;
            }
        } else {
            totalWays += computeWays(chars, length, 2, 5);
            totalWays += computeWays(chars, length, 5, 0);
            totalWays += computeWays(chars, length, 7, 5);
            totalWays += computeWays(chars, length, 0, 0);
        }
        System.out.println(totalWays);
        sc.close();
    }

    static int computeWays(char[] ch, int len, int end1, int end2) {
        if (len == 2 && end1 == 0) return 0;
        int XVal = -1;
        if (ch[len - 2] == 'X') XVal = end1;
        else {
            if (ch[len - 2] != '_') {
                if (getDigit(ch, len - 2) != end1) return 0;
            }
        }
        if (ch[len - 1] == 'X') {
            if (XVal != -1 && end2 != XVal) return 0;
            else XVal = end2;
        } else {
            if (ch[len - 1] != '_') {
                if (getDigit(ch, len - 1) != end2) return 0;
            }
        }
        int totalOptions = 1;
        for (int i = 0; i < len - 2; i++) {
            if (i == 0) {
                if (ch[i] == 'X' && XVal == 0) return 0;
                if (getDigit(ch, i) == 0) return 0;
            }
            if (ch[i] == '_') {
                totalOptions *= (i == 0) ? 9 : 10;
            }
            if (ch[i] == 'X') {
                if (XVal != -1) continue;
                else {
                    XVal = 10;
                    totalOptions *= (i == 0) ? 9 : 10;
                }
            }
        }
        return totalOptions;
    }

    static int getDigit(char[] ch, int pos) {
        if (ch[pos] == '_' || ch[pos] == 'X') return -1;
        return Character.getNumericValue(ch[pos]);
    }
}
